  // C4H7
  ncf[42 * kd + 3] = 4; // C
  ncf[42 * kd + 2] = 7; // H

  // C4H8X1
  ncf[43 * kd + 3] = 4; // C
  ncf[43 * kd + 2] = 8; // H

  // PXC4H9
  ncf[44 * kd + 3] = 4; // C
  ncf[44 * kd + 2] = 9; // H

  // PXC4H9O2
  ncf[45 * kd + 3] = 4; // C
  ncf[45 * kd + 2] = 9; // H
  ncf[45 * kd + 1] = 2; // O

  // C5H9
  ncf[46 * kd + 3] = 5; // C
