  W += c[9] * 1.3018999999999998e+01;  // CH
  W += c[10] * 2.9018000000000001e+01; // HCO
  W += c[11] * 1.4026999999999999e+01; // CH2
  W += c[12] * 4.4009000000000000e+01; // CO2
  W += c[13] * 2.8009999999999998e+01; // CO
  W += c[14] * 3.0026000000000000e+01; // CH2O
