  W += c[17] * 3.1033999999999999e+01; // CH3O
  W += c[18] * 1.6042999999999999e+01; // CH4
  W += c[19] * 3.2042000000000002e+01; // CH3OH
  W += c[20] * 3.0070000000000000e+01; // C2H6
  W += c[21] * 2.9061999999999998e+01; // C2H5
  W += c[22] * 4.2036999999999999e+01; // CH2CO
  W += c[23] * 4.6024999999999999e+01; // HOCHO
  W += c[24] * 4.7033000000000001e+01; // CH3O2
  W += c[25] * 4.8040999999999997e+01; // CH3O2H
  W += c[26] * 2.6037999999999997e+01; // C2H2
  W += c[27] * 4.1028999999999996e+01; // HCCO
  W += c[28] * 2.7045999999999999e+01; // C2H3
  W += c[29] * 4.3045000000000002e+01; // CH2CHO
  W += c[30] * 4.2081000000000003e+01; // C3H6
  W += c[31] * 2.8053999999999998e+01; // C2H4
  W += c[32] * 4.5061000000000000e+01; // C2H5O
  W += c[33] * 4.3045000000000002e+01; // CH3CO
  W += c[34] * 6.1060000000000002e+01; // C2H5O2
  W += c[35] * 3.8048999999999999e+01; // C3H2
  W += c[36] * 3.9057000000000002e+01; // C3H3
  W += c[37] * 4.0064999999999998e+01; // C3H4XA
  W += c[38] * 4.1073000000000000e+01; // C3H5XA
  W += c[39] * 4.3088999999999999e+01; // NXC3H7
  W += c[40] * 7.5087000000000003e+01; // NXC3H7O2
  W += c[41] * 5.4091999999999999e+01; // C4H6
  W += c[42] * 5.5099999999999994e+01; // C4H7
  W += c[43] * 5.6107999999999997e+01; // C4H8X1
  W += c[44] * 5.7116000000000000e+01; // PXC4H9
  W += c[45] * 8.9114000000000004e+01; // PXC4H9O2
