  // reaction 55: CH2 + CO (+M) => CH2CO (+M)
  qf[5] = sc[11] * sc[13];
  qr[5] = 0.0;

  // reaction 56: CO + O (+M) => CO2 (+M)
  qf[6] = sc[1] * sc[13];
  qr[6] = 0.0;

  // reaction 72: CH3O (+M) => CH2O + H (+M)
  qf[7] = sc[17];
