  // reaction 125: CH3CO (+M) => CH3 + CO (+M)
  qf[10] = sc[33];
  qr[10] = 0.0;

  // reaction 4: H + OH + M => H2O + M
  qf[11] = sc[3] * sc[4];
  qr[11] = 0.0;

  // reaction 29: CH2GSG + M => CH2 + M
  qf[12] = sc[15];
  qr[12] = 0.0;

  // reaction 30: CH2 + M => CH2GSG + M
