  kcharge[10] = 0; // HCO
  kcharge[11] = 0; // CH2
  kcharge[12] = 0; // CO2
  kcharge[13] = 0; // CO
  kcharge[14] = 0; // CH2O
  kcharge[15] = 0; // CH2GSG
  kcharge[16] = 0; // CH3
  kcharge[17] = 0; // CH3O
  kcharge[18] = 0; // CH4
  kcharge[19] = 0; // CH3OH
  kcharge[20] = 0; // C2H6
  kcharge[21] = 0; // C2H5
  kcharge[22] = 0; // CH2CO
  kcharge[23] = 0; // HOCHO
  kcharge[24] = 0; // CH3O2
  kcharge[25] = 0; // CH3O2H
  kcharge[26] = 0; // C2H2
  kcharge[27] = 0; // HCCO
  kcharge[28] = 0; // C2H3
  kcharge[29] = 0; // CH2CHO
  kcharge[30] = 0; // C3H6
  kcharge[31] = 0; // C2H4
  kcharge[32] = 0; // C2H5O
  kcharge[33] = 0; // CH3CO
  kcharge[34] = 0; // C2H5O2
  kcharge[35] = 0; // C3H2
  kcharge[36] = 0; // C3H3
  kcharge[37] = 0; // C3H4XA
  kcharge[38] = 0; // C3H5XA
  kcharge[39] = 0; // NXC3H7
  kcharge[40] = 0; // NXC3H7O2
  kcharge[41] = 0; // C4H6
  kcharge[42] = 0; // C4H7
  kcharge[43] = 0; // C4H8X1
  kcharge[44] = 0; // PXC4H9
  kcharge[45] = 0; // PXC4H9O2
  kcharge[46] = 0; // C5H9
  kcharge[47] = 0; // C5H10X1
  kcharge[48] = 0; // C5H11X1
  kcharge[49] = 0; // C6H12X1
