  Bi[0] = 9.5560052221563e-01;
  Fomega[0] = 5.4259343186608e-01;

  // species 1: O
  // Computed from Lennard-Jones
  sqrtOneOverTc[1] = 9.7460146948181e-02;
  sqrtAsti[1] = 4.2500156012386e+04;
  Bi[1] = 6.6930234851885e-01;
  Fomega[1] = 4.8508000000000e-01;

  // species 2: H2
